WITH flagged AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) > INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS is_new_session FROM device_readings), islands AS (SELECT id, device_code, reading_ts, status_bits, firmware, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT id, device_code, status_bits, firmware, session_no FROM islands;
